export const GLOSSARY_SHARD = Object.freeze({"circulating-supply":{"slug":"circulating-supply","cat":"basics","en":"Circulating supply","contentLocale":"id","term":"Circulating supply (suplai beredar)","aka":["suplai beredar","jumlah beredar"],"short":"Circulating supply adalah jumlah koin atau token yang saat ini benar-benar beredar dan bisa diperdagangkan di pasar, tidak termasuk yang masih terkunci atau belum diterbitkan.","body":[["Sebuah ",["aset kripto","cryptocurrency"]," biasanya punya tiga angka suplai. Circulating supply adalah yang beredar sekarang. Total supply adalah yang sudah dibuat dikurangi yang dibakar, termasuk yang terkunci. Max supply adalah batas tertinggi yang pernah bisa ada, misalnya 21 juta untuk ",["Bitcoin","bitcoin"],"."],["Angka ini dipakai untuk menghitung ",["market cap","market-capitalization"],". Circulating supply bisa bertambah lewat ",["token unlock","token-unlock"],", hadiah ",["staking","staking"],", atau ",["penambangan","mining"],", dan bisa berkurang lewat token burn. Perubahan suplai ini memengaruhi seberapa banyak permintaan yang dibutuhkan untuk menjaga harga."],"Definisi beredar tidak selalu seragam. Situs data dan tim proyek bisa berbeda pendapat tentang token di dompet tim atau treasury. Karena itu, bandingkan beberapa sumber dan baca dokumentasi tokenomics proyek."],"example":"Misalkan sebuah token punya max supply 500 juta. Saat ini circulating supply 125 juta, atau 25%. Bulan depan ada unlock 25 juta token untuk investor awal, sehingga suplai beredar menjadi 150 juta. Itu kenaikan 20% dari 125 juta. Jika harga tetap 1 USDT, market cap naik dari 125 juta menjadi 150 juta USDT, artinya pasar harus menyerap 25 juta USDT token tambahan tanpa harga turun.","mistakes":["Menganggap circulating supply selalu tetap, padahal bisa naik karena unlock atau hadiah staking.","Mencampuradukkan circulating supply, total supply, dan max supply saat menghitung valuasi.","Hanya mengandalkan satu situs data padahal definisi suplai bisa berbeda."],"faq":[{"q":"Apa beda circulating supply dan total supply?","a":"Circulating supply hanya menghitung token yang bisa diperdagangkan sekarang. Total supply mencakup token yang sudah dibuat tetapi masih terkunci atau disimpan proyek."},{"q":"Kenapa circulating supply bisa bertambah?","a":"Suplai beredar bertambah ketika token terkunci dibuka, saat ada hadiah penambangan atau staking, atau saat proyek mencetak token baru sesuai aturan tokenomics-nya."}],"title":"Apa itu circulating supply? Arti suplai beredar","description":"Pahami arti circulating supply, bedanya dengan total dan max supply, dan kenapa perubahan suplai memengaruhi harga token.","related":[["market-capitalization","Market capitalization (kapitalisasi pasar)","Market capitalization atau kapitalisasi pasar adalah nilai total sebuah aset kripto yang beredar, dihitung dari harga saat ini dikali jumlah suplai yang beredar."],["fully-diluted-valuation","Fully diluted valuation (FDV)","Fully diluted valuation (FDV) adalah perkiraan nilai sebuah proyek kripto jika seluruh suplai maksimal tokennya sudah beredar, dihitung dari harga saat ini dikali suplai maksimal atau total."],["token-unlock","Token unlock","Token unlock adalah saat sejumlah token yang sebelumnya terkunci, misalnya milik tim atau investor awal, dibuka sesuai jadwal vesting sehingga bisa dipindahkan atau dijual."],["token-burn","Token burn","Token burn adalah penghapusan permanen sejumlah token dari peredaran dengan mengirimnya ke alamat yang tidak bisa diakses siapa pun, sehingga total suplai berkurang."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"bear-market":{"slug":"bear-market","cat":"basics","en":"Bear market","contentLocale":"id","term":"Bear market (pasar bearish)","aka":["bearish","pasar turun","crypto winter"],"short":"Bear market adalah periode ketika harga aset di pasar cenderung turun secara berkelanjutan, biasanya 20% atau lebih dari puncaknya, disertai sentimen pesimis dan volume yang menurun.","body":["Istilah ini berasal dari beruang yang menyerang dengan mencakar ke bawah. Di kripto, bear market panjang sering disebut crypto winter. Harga membentuk puncak dan lembah yang makin rendah, minat pengguna baru menurun, dan banyak proyek kehabisan dana.",["Penurunan di bear market kripto bisa sangat dalam. ",["Bitcoin","bitcoin"]," pernah turun lebih dari 70% dari puncaknya pada beberapa siklus, sedangkan banyak ",["altcoin","altcoin"]," turun lebih dari 90% dan sebagian tidak pernah pulih. Di tengah bear market juga sering muncul kenaikan tajam singkat yang disebut bear market rally."],"Sebagian investor memakai bear market untuk membeli bertahap dengan dollar cost averaging, sementara trader berpengalaman bisa membuka posisi short. Keduanya tetap butuh manajemen risiko, karena dasar harga tidak bisa ditebak."],"example":["Misalkan sebuah altcoin turun dari 10 ",["USDT","usdt"]," ke 1 USDT, penurunan 90%. Untuk kembali ke 10 USDT, harganya harus naik 900%. Jika Anda membeli 100 USDT di harga 5 USDT karena merasa sudah murah, posisi Anda tetap turun menjadi 20 USDT ketika harga mencapai 1 USDT, kerugian 80%. Angka ini menunjukkan kenapa menangkap pisau jatuh berisiko."],"mistakes":["Membeli sekaligus dengan seluruh dana karena harga sudah turun banyak.","Menganggap setiap kenaikan singkat sebagai tanda bear market sudah selesai.","Menyimpan altcoin yang proyeknya sudah tidak aktif dengan harapan pasti pulih."],"faq":[{"q":"Apa beda bear market dan koreksi?","a":"Koreksi adalah penurunan sementara, sering di kisaran 10% sampai 20%, di dalam tren yang lebih besar. Bear market adalah tren turun yang lebih dalam dan lebih lama."},{"q":"Berapa lama bear market kripto berlangsung?","a":"Durasinya tidak pasti. Bear market kripto di masa lalu berlangsung dari beberapa bulan hingga lebih dari setahun, tetapi pola masa lalu tidak menjamin masa depan."}],"title":"Apa itu bear market? Arti bearish di kripto","description":"Arti bear market dan bearish di kripto, seberapa dalam penurunan bisa terjadi, dan kesalahan yang sering dilakukan pemula.","related":[["bull-market","Bull market (pasar bullish)","Bull market adalah periode ketika harga aset di pasar cenderung naik secara berkelanjutan selama berminggu-minggu hingga bertahun-tahun, disertai sentimen optimis dan minat beli yang tinggi."],["fud","FUD (fear, uncertainty, doubt)","FUD adalah singkatan dari fear, uncertainty, and doubt, yaitu informasi atau rumor negatif yang menimbulkan rasa takut dan ragu sehingga mendorong orang menjual aset."],["dollar-cost-averaging","Dollar-cost averaging (DCA)","Dollar-cost averaging (DCA) adalah strategi membeli aset dengan nominal tetap secara berkala, misalnya setiap minggu atau bulan, tanpa memedulikan harga saat itu."],["short-selling","Short selling (jual short)","Short selling adalah strategi mendapat untung dari penurunan harga dengan menjual aset lebih dulu, lalu membelinya kembali di harga lebih rendah untuk menutup posisi."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"leverage":{"slug":"leverage","cat":"derivatives","en":"Leverage","contentLocale":"id","term":"Leverage (daya ungkit)","aka":["daya ungkit","lev","pengali"],"short":"Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT.","body":[["Leverage memperbesar untung dan rugi relatif terhadap margin. Dengan leverage 10x, pergerakan harga 1% berarti untung atau rugi sekitar 10% dari margin. Semakin tinggi leverage, semakin kecil pergerakan harga yang dibutuhkan untuk menghabiskan margin dan memicu ",["likuidasi","liquidation"],"."],["Penting dipahami: risiko sebenarnya ditentukan oleh ",["ukuran posisi","position-sizing"]," dan jarak ",["stop loss","stop-loss"],", bukan angka leverage saja. Posisi 1.000 ",["USDT","usdt"]," dengan leverage 2x atau 10x rugi jumlah yang sama jika harga turun 5%. Bedanya, dengan 10x margin yang dikunci lebih kecil dan ",["harga likuidasi","liquidation-price"]," jauh lebih dekat."],["Exchange membatasi leverage maksimal per pasangan dan menurunkannya untuk posisi besar melalui tingkatan risiko. Banyak exchange menawarkan hingga 100x atau lebih untuk ",["BTC","bitcoin"],", tetapi angka yang tersedia bukan angka yang disarankan."]],"example":"Anda punya 500 USDT dan membuka long BTC dengan leverage 10x, nilai posisi 5.000 USDT, saat BTC di 60.000. Jika BTC naik 3% ke 61.800, keuntungan Anda 150 USDT, atau 30% dari margin. Jika BTC turun 3% ke 58.200, Anda rugi 150 USDT. Dengan leverage 10x di isolated margin, penurunan sekitar 9-10% sudah cukup menghabiskan margin setelah memperhitungkan maintenance margin, jadi likuidasi bisa terjadi di sekitar 54.300.","mistakes":["Memilih leverage tinggi untuk mengejar untung cepat tanpa menghitung harga likuidasi.","Menambah margin ke posisi rugi berkali-kali alih-alih memotong kerugian.","Menganggap leverage rendah otomatis aman padahal ukuran posisinya terlalu besar dibanding akun."],"faq":[{"q":"Berapa leverage yang aman untuk pemula?","a":"Tidak ada angka yang sepenuhnya aman, tetapi banyak trader pemula memulai dengan 2-3x dan ukuran posisi kecil. Pastikan harga likuidasi jauh di luar stop loss Anda."},{"q":"Apakah leverage bisa membuat saya rugi lebih dari modal?","a":"Di kebanyakan exchange kripto, kerugian akun futures dibatasi pada margin yang disetor karena ada likuidasi dan insurance fund. Namun dalam mode cross margin, seluruh saldo akun futures bisa ikut terpakai."}],"title":"Apa itu leverage di trading kripto? Arti dan risikonya","description":"Pelajari leverage di kripto: cara kerja daya ungkit, contoh hitungan untung-rugi, hubungannya dengan likuidasi, dan cara memakainya.","related":[["margin-trading","Margin trading","Margin trading adalah cara trading dengan meminjam dana dari exchange menggunakan aset Anda sebagai jaminan, sehingga Anda bisa membuka posisi lebih besar dari saldo sendiri atau menjual aset yang dipinjam."],["liquidation-price","Harga likuidasi (liquidation price)","Harga likuidasi adalah perkiraan harga mark price di mana posisi leverage Anda akan ditutup paksa karena margin yang tersisa turun ke level maintenance margin."],["initial-margin","Margin awal (initial margin)","Margin awal adalah jumlah jaminan minimum yang harus Anda setor untuk membuka posisi dengan leverage, biasanya sama dengan nilai posisi dibagi leverage yang dipilih."],["isolated-margin","Margin terisolasi (isolated margin)","Margin terisolasi adalah mode margin di mana setiap posisi punya jaminan sendiri yang terpisah, sehingga jika posisi itu dilikuidasi, kerugiannya hanya terbatas pada margin yang dialokasikan ke posisi tersebut."],["position-sizing","Position sizing (ukuran posisi)","Position sizing adalah cara menentukan berapa besar modal yang dipakai untuk satu trade, berdasarkan seberapa banyak kerugian yang siap Anda tanggung jika stop loss tersentuh."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"Leverage 10x: lebih banyak uang, atau lebih banyak risiko?"},"coin":null,"tool":"/liquidations","cta":true},"auto-deleveraging":{"slug":"auto-deleveraging","cat":"derivatives","en":"Auto-deleveraging (ADL)","contentLocale":"id","term":"Auto-deleveraging (ADL)","aka":["ADL","deleveraging otomatis","pengurangan leverage otomatis"],"short":"Auto-deleveraging adalah mekanisme darurat exchange futures yang otomatis menutup sebagian posisi trader yang sedang untung untuk menutup kerugian dari posisi bangkrut, ketika insurance fund tidak cukup.","body":[["Dalam kondisi normal, posisi yang dilikuidasi ditutup di pasar dan sisa kerugiannya ditanggung ",["insurance fund","insurance-fund"],". Namun saat harga bergerak sangat ekstrem, sebagian posisi tidak bisa ditutup di harga yang memadai. Jika insurance fund untuk kontrak itu tidak cukup, exchange memakai ADL: posisi lawan yang paling untung dan paling tinggi ",["leverage","leverage"],"-nya ditutup otomatis pada harga kebangkrutan posisi yang dilikuidasi."],"Exchange menampilkan indikator antrean ADL, biasanya berupa lampu atau bar dari 1 sampai 5. Semakin tinggi keuntungan dan leverage Anda, semakin depan posisi Anda di antrean. Anda tidak rugi karena ADL, tetapi posisi untung Anda ditutup lebih cepat dari rencana, dan Anda kehilangan potensi keuntungan berikutnya.",["ADL jarang terjadi di pasangan besar, tetapi lebih mungkin muncul di ",["altcoin","altcoin"]," dengan ",["likuiditas","liquidity"]," tipis saat terjadi pergerakan ekstrem. Aturan rinci dan cara menghitung antrean berbeda tiap exchange."]],"example":["Misalkan Anda short sebuah altcoin dengan leverage 20x dan sedang untung 150% dari margin, sehingga indikator ADL Anda menyala penuh. Harga tiba-tiba anjlok 35% dalam beberapa menit. Banyak posisi long dilikuidasi, dan insurance fund untuk kontrak itu habis. Exchange menutup 40% posisi short Anda secara otomatis pada harga kebangkrutan sebuah posisi long. Jika short Anda bernilai 10.000 ",["USDT","usdt"],", sekitar 4.000 USDT di antaranya ditutup, keuntungannya terealisasi, dan Anda tidak dikenai ",["biaya trading","maker-taker-fees"]," untuk bagian itu."],"mistakes":["Tidak memperhatikan indikator antrean ADL saat memegang posisi untung besar dengan leverage tinggi.","Mengira posisi yang ditutup ADL berarti dilikuidasi atau rugi.","Menganggap posisi lindung nilai aman, padahal satu sisinya bisa ditutup ADL sehingga hedge menjadi tidak seimbang."],"faq":[{"q":"Apakah saya rugi jika terkena ADL?","a":"Tidak secara langsung. Posisi untung Anda ditutup dan keuntungannya terealisasi, tetapi Anda kehilangan peluang keuntungan lanjutan dan mungkin perlu menyeimbangkan ulang strategi Anda."},{"q":"Bagaimana cara mengurangi risiko terkena ADL?","a":"Gunakan leverage lebih rendah dan ambil sebagian keuntungan saat posisi sudah untung besar. Posisi dengan leverage dan profit tinggi berada paling depan di antrean ADL."}],"title":"Apa itu auto-deleveraging (ADL) di futures kripto?","description":"Pelajari auto-deleveraging atau ADL: kapan exchange menutup posisi untung secara otomatis, cara kerja antrean ADL, dan cara menguranginya.","related":[["insurance-fund","Insurance fund (dana asuransi)","Insurance fund adalah cadangan dana milik exchange futures yang dipakai untuk menutup kerugian ketika posisi yang dilikuidasi ditutup di harga lebih buruk dari harga kebangkrutannya, sehingga trader lain tidak ikut menanggung."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."],["unrealized-pnl","Unrealized PnL (laba/rugi belum terealisasi)","Unrealized PnL adalah keuntungan atau kerugian di atas kertas dari posisi yang masih terbuka, dihitung dari selisih harga masuk dan harga acuan saat ini, dan baru menjadi nyata setelah posisi ditutup."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Likuidasi: siapa yang menekan tombol tutup paksa?"},"coin":null,"tool":"/liquidations","cta":false},"crypto-wallet":{"slug":"crypto-wallet","cat":"wallets-security","en":"Crypto wallet","contentLocale":"id","term":"Dompet kripto (crypto wallet)","aka":["wallet","dompet kripto","crypto wallet","dompet digital kripto"],"short":"Dompet kripto adalah aplikasi, perangkat, atau layanan yang menyimpan kunci untuk mengakses aset kripto Anda di blockchain dan memungkinkan Anda menerima, mengirim, serta menandatangani transaksi.","body":[["Koin Anda sebenarnya tidak tersimpan di dalam dompet, melainkan tercatat di ",["blockchain","blockchain"],". Yang disimpan dompet adalah ",["private key","private-key"],", yaitu kunci yang membuktikan bahwa Anda berhak memindahkan aset di alamat tertentu. Dari private key itu dihasilkan ",["wallet address","wallet-address"]," yang bisa Anda bagikan untuk menerima kripto."],["Ada dua kategori besar. ",["Dompet kustodian","custodial-wallet"],", seperti akun di exchange, menyimpan kunci untuk Anda. ",["Dompet non-kustodian","non-custodial-wallet"],", seperti MetaMask, Trust Wallet, atau ",["hardware wallet","hardware-wallet"],", menyerahkan kunci sepenuhnya kepada Anda, biasanya dalam bentuk seed phrase atau frasa pemulihan 12 atau 24 kata. Dompet juga dibedakan menjadi hot wallet yang terhubung internet dan cold wallet yang disimpan offline."],"Pilihan dompet adalah pilihan tanggung jawab. Dengan dompet non-kustodian, tidak ada pihak yang bisa memulihkan aset jika seed phrase hilang atau dicuri. Simpan seed phrase secara offline, jangan pernah mengetiknya di situs atau membagikannya ke siapa pun."],"example":"Misalkan Anda membeli 300 USDT di exchange lalu ingin memindahkannya ke dompet non-kustodian. Anda membuat dompet baru, mencatat 12 kata seed phrase di kertas, lalu menyalin alamat dompet di jaringan yang sama dengan pilihan penarikan, misalnya jaringan TRON. Exchange memotong biaya penarikan, misalnya 1 USDT, sehingga 299 USDT tiba di dompet Anda. Sebelumnya, Anda sebaiknya mengirim 10 USDT dulu sebagai uji coba untuk memastikan alamat dan jaringannya benar.","mistakes":["Menyimpan seed phrase sebagai foto di galeri ponsel atau di catatan cloud.","Mengirim token lewat jaringan yang berbeda dari jaringan alamat penerima.","Memasukkan seed phrase ke situs atau aplikasi yang mengaku sebagai dukungan pelanggan."],"faq":[{"q":"Dompet kripto mana yang paling aman?","a":"Hardware wallet yang dipakai dengan benar umumnya paling aman untuk penyimpanan jangka panjang. Untuk transaksi harian, hot wallet atau akun exchange lebih praktis tetapi lebih terpapar risiko online."},{"q":"Apa yang terjadi jika saya kehilangan seed phrase?","a":"Jika perangkat Anda juga hilang atau rusak, aset di dompet non-kustodian tidak bisa dipulihkan oleh siapa pun. Karena itu cadangan seed phrase offline sangat penting."}],"title":"Apa itu dompet kripto? Arti, jenis, dan cara kerjanya","description":"Pelajari apa itu dompet kripto, peran private key dan seed phrase, beda dompet kustodian dan non-kustodian, serta hot dan cold wallet.","related":[["custodial-wallet","Dompet kustodian (custodial wallet)","Dompet kustodian adalah dompet kripto di mana pihak ketiga, biasanya exchange, menyimpan dan mengelola private key untuk Anda, sehingga Anda mengakses aset lewat akun, bukan lewat kunci sendiri."],["non-custodial-wallet","Dompet non-kustodian (self-custody wallet)","Dompet non-kustodian adalah dompet kripto di mana hanya Anda yang memegang private key, sehingga tidak ada pihak lain yang bisa memindahkan, membekukan, atau memulihkan aset Anda."],["seed-phrase","Seed phrase (frasa pemulihan)","Seed phrase adalah rangkaian 12 atau 24 kata acak yang menjadi cadangan utama dompet kripto, karena dari kata-kata inilah semua private key dan alamat dompet Anda bisa dibuat ulang."],["wallet-address","Alamat dompet (wallet address)","Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu."],["hardware-wallet","Hardware wallet (dompet perangkat keras)","Hardware wallet adalah perangkat fisik khusus yang menyimpan private key secara offline dan menandatangani transaksi di dalam perangkat, sehingga kunci tidak pernah terekspos ke komputer atau ponsel."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Di mana koin saya? Bursa vs dompet"},"coin":null,"tool":null,"cta":false},"memo-tag":{"slug":"memo-tag","cat":"wallets-security","en":"Memo / destination tag","contentLocale":"id","term":"Memo / destination tag","aka":["memo","tag","destination tag","MEMO tag"],"short":"Memo atau destination tag adalah kode tambahan selain alamat yang dipakai beberapa jaringan, seperti XRP, Stellar, TON, atau Cosmos, untuk menandai akun penerima di dalam satu alamat bersama milik exchange.","body":["Beberapa exchange memakai satu alamat untuk menampung deposit banyak pengguna pada koin tertentu. Agar sistem tahu deposit itu milik siapa, setiap pengguna diberi memo atau tag unik. Di XRP disebut destination tag, di Stellar dan TON sering disebut memo, dan di jaringan lain bisa disebut comment.","Jika halaman deposit exchange menampilkan memo, Anda wajib mengisinya saat mengirim. Tanpa memo, dana tetap sampai ke alamat exchange, tetapi tidak otomatis masuk ke akun Anda. Pemulihannya harus lewat tiket dukungan, bisa memakan waktu, dan tergantung kebijakan platform.",["Sebaliknya, ",["dompet pribadi","non-custodial-wallet"]," biasanya tidak membutuhkan memo karena alamatnya hanya milik Anda. Jadi aturan praktisnya: ikuti persis apa yang ditampilkan di halaman deposit tujuan, baik alamat, jaringan, maupun memo."]],"example":"Anda ingin mengirim 150 XRP dari dompet pribadi ke exchange. Halaman deposit exchange menampilkan alamat yang diawali r dan destination tag 482915. Anda menempelkan alamat, lalu mengetik 482915 di kolom tag. Setelah beberapa detik, 150 XRP masuk ke saldo akun Anda. Jika kolom tag dibiarkan kosong, 150 XRP itu tiba di alamat exchange tetapi tidak terkredit ke akun mana pun sampai Anda mengajukan tiket.","mistakes":["Mengosongkan kolom memo karena dianggap opsional, padahal exchange tujuan mewajibkannya.","Memakai memo dari deposit lama atau milik akun lain.","Mengisi memo saat mengirim ke dompet pribadi yang tidak memerlukannya, lalu mengira itu penyebab dana hilang."],"faq":[{"q":"Apa yang terjadi jika saya lupa memo?","a":"Dana biasanya sampai di alamat exchange tetapi tidak terkredit otomatis. Hubungi dukungan resmi exchange dengan TxID untuk meminta pemulihan; prosesnya dan biayanya berbeda di tiap platform."},{"q":"Apakah semua koin perlu memo?","a":"Tidak. Bitcoin, Ethereum, dan sebagian besar token EVM tidak memakai memo. Memo umumnya diperlukan pada jaringan seperti XRP, Stellar, TON, EOS, atau Cosmos saat deposit ke exchange."}],"title":"Apa itu memo atau destination tag di transfer kripto?","description":"Arti memo dan destination tag, kapan wajib diisi saat deposit ke exchange, dan apa yang harus dilakukan jika lupa mengisinya.","related":[["wallet-address","Alamat dompet (wallet address)","Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu."],["blockchain-network","Jaringan deposit (pilihan chain)","Jaringan deposit adalah blockchain yang Anda pilih untuk mengirim atau menerima sebuah aset, misalnya USDT lewat Tron, Ethereum, atau BNB Smart Chain, dan pilihan ini harus sama di sisi pengirim dan penerima."],["transaction-hash","Transaction hash (TxID)","Transaction hash atau TxID adalah kode unik untuk setiap transaksi di blockchain, yang bisa Anda pakai untuk melacak status transfer di block explorer."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Sebelum transfer: jangan tebak-tebak hal-hal ini"},"coin":null,"tool":null,"cta":false},"two-factor-authentication":{"slug":"two-factor-authentication","cat":"wallets-security","en":"Two-factor authentication (2FA)","contentLocale":"id","term":"Autentikasi dua faktor (2FA)","aka":["2FA","verifikasi dua langkah","two-factor authentication","Google Authenticator"],"short":"Autentikasi dua faktor (2FA) adalah lapisan keamanan yang meminta bukti kedua selain kata sandi, misalnya kode dari aplikasi autentikator atau kunci keamanan fisik, sebelum Anda bisa login atau menarik dana.","body":[["Kata sandi saja mudah bocor lewat ",["phishing","phishing"]," atau kebocoran data situs lain. Dengan 2FA, penyerang yang tahu kata sandi Anda tetap butuh faktor kedua yang hanya ada di perangkat Anda."],"Ada beberapa jenis 2FA. SMS paling mudah tetapi paling lemah karena rentan SIM swap, yaitu penipu mengambil alih nomor ponsel Anda lewat operator. Aplikasi autentikator seperti Google Authenticator atau Authy membuat kode 6 digit yang berganti setiap 30 detik dan jauh lebih kuat. Kunci keamanan fisik (passkey atau kunci FIDO) adalah opsi paling tahan phishing.",["Di exchange, aktifkan 2FA bukan hanya untuk login tetapi juga untuk penarikan dan perubahan pengaturan keamanan. Simpan kode cadangan (backup key) 2FA secara offline. Jika ponsel hilang tanpa cadangan, proses pemulihan akun di exchange bisa memakan waktu berhari-hari dan membutuhkan ",["verifikasi identitas","kyc"]," ulang."]],"example":["Misalnya kata sandi akun exchange Anda bocor dari kebocoran data situs belanja yang memakai kata sandi sama. Pukul 02.00 seseorang mencoba login dari negara lain. Exchange meminta kode 6 digit dari aplikasi autentikator. Penyerang tidak punya ponsel Anda, sehingga setelah 3 kali gagal, akun dikunci sementara dan Anda menerima email peringatan. Saldo 3.000 ",["USDT","usdt"]," Anda tetap utuh, dan Anda segera mengganti kata sandi."],"mistakes":["Hanya memakai 2FA lewat SMS untuk akun dengan saldo besar.","Tidak mencatat kode cadangan 2FA, lalu kehilangan akses saat ganti ponsel.","Memberikan kode 2FA kepada orang yang mengaku sebagai petugas exchange lewat telepon atau chat."],"faq":[{"q":"2FA mana yang paling aman untuk exchange kripto?","a":"Kunci keamanan fisik atau passkey paling tahan phishing, disusul aplikasi autentikator. SMS sebaiknya hanya dipakai jika tidak ada pilihan lain."},{"q":"Apa yang harus dilakukan jika ponsel dengan aplikasi 2FA hilang?","a":"Gunakan kode cadangan untuk memasang 2FA di ponsel baru. Jika tidak punya cadangan, ajukan reset 2FA melalui menu resmi exchange dan siapkan verifikasi identitas."}],"title":"Apa itu 2FA? Arti autentikasi dua faktor di exchange","description":"Pelajari arti 2FA, beda SMS, aplikasi autentikator, dan passkey, serta cara mengamankan akun exchange kripto Anda.","related":[["anti-phishing-code","Kode anti-phishing","Kode anti-phishing adalah kata atau kode rahasia yang Anda tetapkan di akun exchange, lalu dicantumkan di setiap email resmi exchange agar Anda bisa membedakannya dari email palsu."],["withdrawal-whitelist","Whitelist penarikan (withdrawal whitelist)","Whitelist penarikan adalah fitur keamanan exchange yang membatasi penarikan hanya ke alamat yang sudah Anda daftarkan dan verifikasi sebelumnya."],["phishing","Phishing (penipuan pancingan)","Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya."],["sub-account","Sub-akun (sub-account)","Sub-akun adalah akun tambahan di bawah akun utama bursa yang punya saldo, posisi, dan API key terpisah, sehingga Anda bisa memisahkan strategi atau dana tanpa membuat akun baru dengan KYC lain."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Temukan pintu yang asli: Jangan buka akun sembarangan"},"coin":null,"tool":null,"cta":false},"withdrawal-whitelist":{"slug":"withdrawal-whitelist","cat":"wallets-security","en":"Withdrawal whitelist","contentLocale":"id","term":"Whitelist penarikan (withdrawal whitelist)","aka":["withdrawal whitelist","daftar putih penarikan","whitelist alamat"],"short":"Whitelist penarikan adalah fitur keamanan exchange yang membatasi penarikan hanya ke alamat yang sudah Anda daftarkan dan verifikasi sebelumnya.","body":[["Tanpa whitelist, siapa pun yang berhasil masuk ke akun Anda bisa menarik dana ke alamat mana saja. Dengan whitelist aktif, penarikan hanya bisa dikirim ke alamat dalam daftar. Menambahkan alamat baru biasanya memerlukan ",["2FA","two-factor-authentication"],", ",["konfirmasi","block-confirmations"]," email, dan di banyak exchange ada masa tunggu, misalnya 24 jam, sebelum alamat baru bisa dipakai."],"Masa tunggu itulah yang memberi Anda waktu bereaksi. Jika Anda menerima notifikasi alamat baru ditambahkan padahal Anda tidak melakukannya, Anda bisa segera membekukan akun lewat menu keamanan atau dukungan resmi.",["Whitelist juga membantu melawan ",["address poisoning","address-poisoning"]," dan kesalahan salin-tempel. Alamat yang sudah diuji dan diberi label jelas, misalnya ",["hardware wallet","hardware-wallet"]," atau exchange kedua, mengurangi risiko Anda menempelkan alamat yang salah. Nama fitur, lama masa tunggu, dan opsinya berbeda di tiap exchange."]],"example":["Misalnya Anda mendaftarkan dua alamat di whitelist: hardware wallet ",["BTC","bitcoin"]," dan dompet ",["USDT","usdt"]," TRC20, masing-masing sudah diuji dengan transfer kecil. Suatu hari kata sandi dan email Anda dibobol. Penyerang mencoba menarik 2.500 USDT ke alamatnya sendiri, tetapi sistem menolak karena alamat itu tidak ada di whitelist. Saat ia mencoba menambahkan alamat baru, masa tunggu 24 jam berlaku dan Anda menerima notifikasi, lalu membekukan akun sebelum dana keluar."],"mistakes":["Menonaktifkan whitelist karena merasa repot setiap kali menambah alamat baru.","Mendaftarkan alamat dari riwayat transaksi tanpa memverifikasi sumber aslinya.","Tidak memberi label pada alamat sehingga bingung memilih saat penarikan."],"faq":[{"q":"Apakah whitelist penarikan wajib diaktifkan?","a":"Tidak wajib, tetapi sangat disarankan jika Anda menyimpan saldo besar di exchange atau sering menarik ke alamat yang sama."},{"q":"Mengapa alamat baru tidak bisa langsung dipakai?","a":"Banyak exchange menerapkan masa tunggu setelah alamat baru ditambahkan agar pemilik akun punya waktu menghentikan penarikan jika akunnya dibobol."}],"title":"Apa itu whitelist penarikan? Fitur keamanan exchange","description":"Pelajari arti whitelist penarikan, cara kerjanya, dan bagaimana fitur ini melindungi saldo exchange Anda dari penarikan tidak sah.","related":[["wallet-address","Alamat dompet (wallet address)","Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu."],["two-factor-authentication","Autentikasi dua faktor (2FA)","Autentikasi dua faktor (2FA) adalah lapisan keamanan yang meminta bukti kedua selain kata sandi, misalnya kode dari aplikasi autentikator atau kunci keamanan fisik, sebelum Anda bisa login atau menarik dana."],["address-poisoning","Address poisoning (peracunan alamat)","Address poisoning adalah penipuan di mana pelaku mengirim transaksi bernilai kecil atau nol dari alamat yang mirip dengan alamat yang sering Anda pakai, berharap Anda menyalin alamat palsu itu dari riwayat transaksi."],["anti-phishing-code","Kode anti-phishing","Kode anti-phishing adalah kata atau kode rahasia yang Anda tetapkan di akun exchange, lalu dicantumkan di setiap email resmi exchange agar Anda bisa membedakannya dari email palsu."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Sebelum transfer: jangan tebak-tebak hal-hal ini"},"coin":null,"tool":null,"cta":false},"crypto-backed-stablecoin":{"slug":"crypto-backed-stablecoin","cat":"stablecoins","en":"Crypto-backed stablecoin","contentLocale":"id","term":"Stablecoin berjaminan kripto (crypto-backed stablecoin)","aka":["crypto-backed stablecoin","stablecoin overcollateralized"],"short":"Stablecoin berjaminan kripto adalah stablecoin yang dicetak dengan mengunci aset kripto seperti ETH sebagai jaminan dengan nilai lebih besar daripada stablecoin yang diterbitkan.","body":[["Berbeda dengan ",["USDT","usdt"]," atau ",["USDC","usdc"]," yang didukung kas dan surat utang di rekening penerbit, ",["stablecoin","stablecoin"]," jenis ini didukung ",["aset kripto","cryptocurrency"]," yang terkunci di ",["smart contract","smart-contract"],". Contoh paling dikenal adalah DAI dari MakerDAO, yang kini juga punya versi baru bernama USDS di ekosistem Sky."],"Karena harga kripto naik turun, sistemnya memakai overcollateralization: jaminan harus bernilai jauh di atas utang. Jika nilai jaminan turun mendekati batas minimum, posisi akan dilikuidasi otomatis. Jaminan dijual untuk menutup stablecoin yang dicetak, ditambah penalti.",["Kelebihannya transparan, karena semua jaminan bisa dicek di ",["blockchain","blockchain"],". Kekurangannya, modal Anda kurang efisien, ada risiko bug smart contract, dan risiko likuidasi saat pasar jatuh cepat. Sebagian protokol juga menambahkan aset lain sebagai jaminan, sehingga profil risikonya perlu dicek satu per satu."]],"example":"Misalkan Anda mengunci 2 ETH dengan harga 3.000 USDT per ETH, jadi jaminan bernilai 6.000. Protokol mensyaratkan rasio jaminan minimal 150%. Anda mencetak 3.000 DAI, sehingga rasio Anda 200%. Jika ETH turun ke 2.250, jaminan tinggal 4.500 atau tepat 150%, dan posisi Anda berada di ambang likuidasi. Kalau ETH turun lebih jauh, sebagian jaminan dijual dan Anda terkena penalti. Untuk menghindarinya, Anda bisa menambah jaminan atau melunasi sebagian DAI sebelum harga mencapai batas itu.","mistakes":["Mencetak stablecoin sampai mepet batas minimum sehingga koreksi kecil sudah memicu likuidasi.","Mengira stablecoin berjaminan kripto bebas risiko karena jaminannya lebih dari 100%.","Tidak memantau harga jaminan saat pasar bergejolak di malam hari atau akhir pekan."],"faq":[{"q":"Apakah DAI termasuk stablecoin berjaminan kripto?","a":"Ya, DAI awalnya dijamin aset kripto seperti ETH. Kini jaminannya juga mencakup aset lain, termasuk stablecoin dan aset dunia nyata, sehingga komposisinya perlu dicek langsung di dasbor protokol."},{"q":"Kenapa jaminannya harus lebih besar dari nilai stablecoin?","a":"Karena harga kripto bisa turun tajam. Jaminan berlebih memberi ruang penyangga sebelum nilai jaminan jatuh di bawah nilai stablecoin yang beredar."}],"title":"Apa itu stablecoin berjaminan kripto? Cara kerjanya","description":"Pahami stablecoin berjaminan kripto seperti DAI: cara mencetaknya, rasio jaminan, dan bagaimana likuidasi terjadi.","related":[["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["defi-lending","DeFi lending (pinjam-meminjam DeFi)","DeFi lending adalah layanan pinjam-meminjam kripto lewat smart contract, di mana pemberi pinjaman mendapat bunga dan peminjam harus menyetor jaminan melebihi nilai pinjamannya."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."],["algorithmic-stablecoin","Stablecoin algoritmik (algorithmic stablecoin)","Stablecoin algoritmik adalah stablecoin yang mencoba menjaga patokan harga lewat aturan kode dan insentif pasar, bukan lewat cadangan kas penuh atau jaminan berlebih."]],"lesson":null,"coin":{"slug":"dai","name":"Dai","symbol":"DAI"},"tool":null,"cta":false},"block-explorer":{"slug":"block-explorer","cat":"onchain","en":"Block explorer","contentLocale":"id","term":"Block explorer","aka":["blockchain explorer","penjelajah blok"],"short":"Block explorer adalah situs atau aplikasi untuk mencari dan melihat data blockchain secara publik, seperti status transaksi, saldo alamat, isi blok, dan jumlah konfirmasi.","body":[["Setiap ",["blockchain","blockchain"]," punya explorer sendiri. Etherscan untuk ",["Ethereum","ethereum"],", Tronscan untuk jaringan TRON, BscScan untuk BNB Chain, Solscan untuk Solana, dan ",["mempool","mempool"],".space untuk ",["Bitcoin","bitcoin"]," adalah contoh yang umum dipakai. Anda cukup menempelkan ",["hash transaksi","transaction-hash"]," (TxID) atau ",["alamat dompet","wallet-address"]," di kolom pencarian."],"Explorer paling berguna saat transfer belum masuk. Anda bisa melihat apakah transaksi masih pending, sudah dikonfirmasi, atau gagal. Anda juga bisa mengecek apakah alamat tujuan dan jaringan sudah benar, berapa biaya gas yang dibayar, dan berapa konfirmasi yang sudah didapat.","Pastikan explorer yang Anda buka sesuai jaringan transaksi. USDT di TRON tidak akan muncul di Etherscan. Ingat juga bahwa explorer hanya menampilkan data publik; ia tidak bisa membatalkan transaksi dan tidak pernah meminta seed phrase Anda."],"example":"Misalkan Anda menarik 200 USDT dari bursa ke dompet lewat jaringan TRC20, tetapi setelah 15 menit saldo belum bertambah. Salin TxID dari riwayat penarikan, lalu buka Tronscan. Jika statusnya sudah sukses dengan, misalnya, 25 konfirmasi dan alamat tujuannya cocok, berarti dana sudah sampai di alamat itu dan masalahnya mungkin di tampilan dompet, misalnya token belum ditambahkan. Jika TxID belum muncul sama sekali, kemungkinan bursa belum menyiarkan transaksi, sehingga Anda perlu menghubungi dukungan bursa.","mistakes":["Mencari transaksi di explorer jaringan yang salah lalu mengira dana hilang.","Memasukkan seed phrase atau private key ke situs yang mengaku sebagai explorer.","Mengira status pending di explorer berarti transaksi gagal."],"faq":[{"q":"Bagaimana cara mengecek transaksi kripto?","a":"Salin hash transaksi atau TxID dari riwayat bursa atau dompet, lalu tempelkan di block explorer jaringan yang sesuai. Anda akan melihat status, jumlah konfirmasi, alamat, dan biayanya."},{"q":"Apakah block explorer aman?","a":"Explorer resmi aman untuk melihat data karena tidak butuh login. Pastikan alamat situsnya benar dan jangan pernah memasukkan seed phrase atau menghubungkan dompet tanpa alasan jelas."}],"title":"Apa itu block explorer? Cara cek transaksi kripto","description":"Pelajari fungsi block explorer seperti Etherscan dan Tronscan, cara mengecek TxID, status transfer, dan konfirmasi.","related":[["transaction-hash","Transaction hash (TxID)","Transaction hash atau TxID adalah kode unik untuk setiap transaksi di blockchain, yang bisa Anda pakai untuk melacak status transfer di block explorer."],["block-confirmations","Konfirmasi blok (block confirmations)","Konfirmasi blok adalah jumlah blok yang sudah ditambahkan sejak transaksi Anda masuk ke blockchain, dan semakin banyak konfirmasi berarti semakin kecil kemungkinan transaksi itu dibatalkan."],["wallet-address","Alamat dompet (wallet address)","Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu."],["on-chain-analysis","Analisis on-chain","Analisis on-chain adalah cara membaca data transaksi yang tercatat di blockchain, seperti aliran dana ke bursa, aktivitas alamat, dan pergerakan whale, untuk memahami perilaku pelaku pasar."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Tertulis terkirim, tapi belum sampai. Harus cek ke mana?"},"coin":null,"tool":null,"cta":false},"travel-rule":{"slug":"travel-rule","cat":"regulation","en":"Travel rule","contentLocale":"id","term":"Travel rule","aka":["aturan travel rule","FATF travel rule"],"short":"Travel rule adalah aturan yang mewajibkan penyedia jasa aset kripto mengirim dan menerima data pengirim serta penerima bersama transfer kripto, mengikuti Rekomendasi 16 FATF.","body":[["Aturan ini berasal dari perbankan, di mana data nasabah ikut berpindah bersama transfer antarbank. FATF menerapkannya ke ",["aset kripto","cryptocurrency"],". Dalam panduan FATF, ambang batasnya adalah 1.000 dolar AS atau euro, tetapi tiap negara bisa menetapkan aturan sendiri. Uni Eropa misalnya menerapkannya sejak euro pertama mulai 30 Desember 2024."],["Dampaknya bagi Anda: saat menarik kripto, bursa bisa meminta nama penerima, apakah tujuannya bursa lain atau ",["dompet pribadi","non-custodial-wallet"],", dan nama bursa tujuan. Saat menerima setoran, bursa bisa meminta informasi pengirim. Jika data tidak cocok, transfer bisa tertahan atau dikembalikan."],["Penerapannya berbeda antarbursa karena mereka memakai sistem pertukaran data yang berbeda. Transfer antara dua bursa yang belum terhubung bisa butuh verifikasi manual. Untuk dompet pribadi, beberapa bursa meminta ",["bukti kepemilikan","proof-of-stake"],", misalnya tanda tangan pesan."]],"example":["Misalkan Anda menarik 1.500 ",["USDT","usdt"]," dari bursa A ke akun Anda sendiri di bursa B. Bursa A meminta Anda memilih tujuan bursa B dan mengisi nama penerima sesuai ",["KYC","kyc"]," di bursa B. Jika Anda menulis nama panggilan, bukan nama lengkap di KTP, bursa B bisa gagal mencocokkan data dan menahan setoran. Akibatnya dana 1.500 USDT tertunda sampai Anda melengkapi informasi. Dengan mengisi nama persis sesuai identitas, transfer biasanya diproses normal."],"mistakes":["Mengisi nama penerima tidak sesuai identitas yang dipakai saat KYC di bursa tujuan.","Memilih jenis tujuan yang salah, misalnya dompet pribadi padahal tujuannya bursa.","Mengira travel rule hanya berlaku untuk transfer di atas 1.000 dolar di semua negara."],"faq":[{"q":"Kenapa bursa menanyakan data penerima saat penarikan?","a":"Karena travel rule mewajibkan bursa mengirim data pengirim dan penerima bersama transfer. Informasi ini dipakai untuk mencegah pencucian uang dan pendanaan terorisme."},{"q":"Apakah travel rule berlaku untuk dompet pribadi?","a":"Bisa berlaku, tergantung aturan negara dan kebijakan bursa. Beberapa bursa meminta Anda menyatakan kepemilikan dompet atau membuktikannya sebelum penarikan diproses."}],"title":"Apa itu travel rule kripto? Arti dan dampaknya","description":"Pahami travel rule FATF untuk transfer kripto, data yang diminta bursa, dan cara agar penarikan Anda tidak tertahan.","related":[["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."],["aml","AML (anti pencucian uang)","AML adalah kumpulan aturan dan prosedur untuk mencegah dana hasil kejahatan dicuci lewat sistem keuangan, termasuk lewat bursa dan transfer aset kripto."],["vasp","VASP (penyedia jasa aset virtual)","VASP adalah istilah FATF untuk perusahaan yang menyediakan jasa aset kripto bagi orang lain, seperti bursa, penyedia kustodi, dan layanan transfer, yang wajib mematuhi aturan AML dan KYC."],["withdrawal-whitelist","Whitelist penarikan (withdrawal whitelist)","Whitelist penarikan adalah fitur keamanan exchange yang membatasi penarikan hanya ke alamat yang sudah Anda daftarkan dan verifikasi sebelumnya."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Sebelum transfer: jangan tebak-tebak hal-hal ini"},"coin":null,"tool":null,"cta":false},"spot-bitcoin-etf":{"slug":"spot-bitcoin-etf","cat":"regulation","en":"Spot bitcoin ETF","contentLocale":"id","term":"ETF Bitcoin spot","aka":["spot bitcoin ETF","ETF BTC spot","Bitcoin ETF"],"short":"ETF Bitcoin spot adalah reksa dana yang diperdagangkan di bursa saham dan memegang bitcoin asli sebagai aset dasarnya, sehingga harga sahamnya mengikuti harga BTC.","body":[["ETF spot ",["Bitcoin","bitcoin"]," di Amerika Serikat mulai diperdagangkan pada Januari 2024. Penerbitnya membeli BTC dan menyimpannya di kustodian. Investor membeli saham ETF lewat broker saham, tanpa perlu ",["dompet kripto","crypto-wallet"],", ",["seed phrase","seed-phrase"],", atau akun ",["bursa kripto","centralized-exchange"],"."],["Berbeda dengan ETF berbasis futures yang memegang ",["kontrak berjangka","futures-contract"],", ETF spot memegang koin sebenarnya. Pemegang ETF membayar biaya pengelolaan tahunan yang dipotong dari nilai aset, dan hanya bisa berdagang pada jam bursa saham, sementara pasar kripto buka 24 jam."],"Bagi pasar kripto, arus dana masuk dan keluar ETF menjadi data yang diamati karena mencerminkan permintaan investor tradisional. Bagi investor di Indonesia, akses ke ETF AS tergantung broker yang menyediakan saham luar negeri. Memiliki ETF berarti Anda tidak memegang BTC sendiri dan tidak bisa menariknya ke dompet."],"example":"Misalkan Anda membeli saham ETF Bitcoin spot senilai 1.000 dolar dengan biaya pengelolaan 0,25% per tahun. Setelah setahun, jika harga BTC tidak berubah, nilai investasi Anda sekitar 997,50 dolar karena dipotong biaya 2,50 dolar. Bandingkan dengan membeli BTC langsung senilai 1.000 dolar di bursa dengan biaya transaksi 0,1%, yaitu 1 dolar, lalu menyimpannya di dompet sendiri tanpa biaya tahunan. Namun pilihan kedua menuntut Anda menjaga seed phrase dan keamanan dompet sendiri.","mistakes":["Mengira membeli saham ETF sama dengan memiliki BTC yang bisa ditarik ke dompet.","Lupa bahwa ETF hanya diperdagangkan pada jam bursa saham, sementara harga BTC bergerak 24 jam.","Mengabaikan biaya pengelolaan tahunan dalam perhitungan jangka panjang."],"faq":[{"q":"Kapan ETF Bitcoin spot pertama diperdagangkan di AS?","a":"ETF spot Bitcoin mulai diperdagangkan di Amerika Serikat pada Januari 2024. Sejak itu arus dana masuk dan keluarnya sering dipantau pelaku pasar."},{"q":"Apa beda ETF Bitcoin spot dan ETF futures?","a":"ETF spot memegang bitcoin asli, sedangkan ETF futures memegang kontrak berjangka Bitcoin. ETF futures bisa menanggung biaya rollover sehingga kinerjanya dapat menyimpang dari harga spot."}],"title":"Apa itu ETF Bitcoin spot? Arti dan cara kerjanya","description":"Pahami ETF Bitcoin spot, bedanya dengan memegang BTC langsung dan ETF futures, serta biaya yang perlu Anda hitung.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) adalah aset kripto pertama yang diluncurkan pada 2009, berjalan di jaringan terdesentralisasi dengan proof of work dan jumlah maksimal 21 juta koin."],["tokenized-stocks","Saham tokenisasi (tokenized stocks)","Saham tokenisasi adalah token di blockchain yang mewakili atau mengikuti harga saham nyata, seperti saham perusahaan AS, sehingga bisa diperdagangkan di platform kripto, sering 24 jam."],["custodial-wallet","Dompet kustodian (custodial wallet)","Dompet kustodian adalah dompet kripto di mana pihak ketiga, biasanya exchange, menyimpan dan mengelola private key untuk Anda, sehingga Anda mengakses aset lewat akun, bukan lewat kunci sendiri."],["market-capitalization","Market capitalization (kapitalisasi pasar)","Market capitalization atau kapitalisasi pasar adalah nilai total sebuah aset kripto yang beredar, dihitung dari harga saat ini dikali jumlah suplai yang beredar."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"geo-restrictions":{"slug":"geo-restrictions","cat":"regulation","en":"Geo-restrictions (restricted regions)","contentLocale":"id","term":"Pembatasan wilayah (geo-restrictions)","aka":["geo-restriction","wilayah terbatas","negara terlarang"],"short":"Pembatasan wilayah adalah aturan bursa kripto yang melarang atau membatasi layanan bagi pengguna dari negara tertentu karena alasan regulasi, izin, atau sanksi internasional.","body":[["Hampir setiap bursa global punya daftar wilayah terbatas di syarat layanannya. Ada yang melarang semua layanan, ada yang hanya membatasi produk tertentu seperti ",["perpetual futures","perpetual-futures"],", ",["leverage","leverage"]," tinggi, earn, atau token tertentu. Daftar ini berbeda antarbursa dan bisa berubah saat aturan suatu negara berubah."],["Bursa menentukan wilayah Anda dari data ",["KYC","kyc"],", alamat IP, nomor telepon, dan dokumen tempat tinggal. Memakai VPN untuk menyamarkan lokasi biasanya melanggar syarat layanan. Jika terdeteksi, akun bisa dibatasi, dan penarikan dana bisa membutuhkan verifikasi tambahan."],"Bagi pengguna di Indonesia, cek apakah bursa melayani Indonesia secara resmi dan produk apa yang tersedia. Regulator Indonesia juga dapat memblokir akses ke platform yang tidak berizin. Baca bagian wilayah terbatas sebelum menyetor, bukan setelah dana masuk."],"example":["Misalkan Anda pindah kerja dari Jakarta ke negara yang masuk daftar terbatas sebuah bursa. Anda masih punya 1.200 ",["USDT","usdt"]," dan posisi perpetual terbuka dengan margin 300 USDT. Setelah bursa mendeteksi alamat IP dan dokumen baru, akun Anda diubah ke mode tutup posisi saja: Anda tidak bisa membuka posisi baru, hanya menutup posisi dan menarik dana. Anda perlu menutup posisi dan menarik total 1.500 USDT dalam batas waktu yang diberikan. Jika Anda mengetahuinya lebih awal, Anda bisa merencanakannya tanpa terburu-buru."],"mistakes":["Memakai VPN untuk mengakses bursa yang melarang wilayah Anda.","Tidak membaca daftar wilayah terbatas sebelum menyetor dana.","Mengira semua produk bursa tersedia sama di setiap negara."],"faq":[{"q":"Apa yang terjadi jika memakai VPN di bursa kripto?","a":"Banyak bursa melarangnya dalam syarat layanan. Jika terdeteksi, akun bisa dibatasi atau dibekukan dan penarikan dana bisa membutuhkan pemeriksaan tambahan."},{"q":"Kenapa produk futures tidak tersedia di negara saya?","a":"Bursa menyesuaikan produk dengan aturan setempat dan izin yang dimiliki. Produk derivatif sering lebih dibatasi daripada perdagangan spot."}],"title":"Apa itu pembatasan wilayah di bursa kripto?","description":"Pahami geo-restrictions di bursa kripto: alasan negara dibatasi, cara bursa mendeteksi lokasi, dan risiko memakai VPN.","related":[["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh."],["vasp","VASP (penyedia jasa aset virtual)","VASP adalah istilah FATF untuk perusahaan yang menyediakan jasa aset kripto bagi orang lain, seperti bursa, penyedia kustodi, dan layanan transfer, yang wajib mematuhi aturan AML dan KYC."],["no-kyc-exchange","Bursa tanpa KYC (no-KYC exchange)","Bursa tanpa KYC adalah platform yang mengizinkan Anda berdagang atau menarik kripto tanpa verifikasi identitas, biasanya dengan batas penarikan tertentu atau sebagai bursa terdesentralisasi."],["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"Bagaimana cara kerja KYC dan kepada siapa identitas diberikan?"},"coin":null,"tool":"/exchanges","cta":false},"delisting":{"slug":"delisting","cat":"exchange-features","en":"Delisting","contentLocale":"id","term":"Delisting","aka":["delist","penghapusan token","koin di-delist"],"short":"Delisting adalah keputusan bursa untuk menghapus token atau pasangan perdagangan dari platformnya, sehingga perdagangan dihentikan dan pengguna diberi batas waktu untuk menarik aset.","body":[["Alasan umum delisting antara lain ",["likuiditas","liquidity"]," dan volume rendah, proyek tidak aktif, masalah keamanan, pelanggaran standar bursa, atau perubahan regulasi. Bursa biasanya mengumumkan lebih dulu, misalnya beberapa hari sebelum perdagangan dihentikan, lalu memberi waktu lebih lama untuk penarikan."],["Ada tingkatan berbeda. Kadang hanya satu pasangan yang dihapus, misalnya pasangan dengan ",["BTC","bitcoin"],", sementara pasangan dengan ",["USDT","usdt"]," tetap ada. Ada juga delisting total, di mana setoran, perdagangan, dan akhirnya penarikan ditutup. ",["Perpetual futures","perpetual-futures"]," untuk token itu juga bisa ditutup dan posisi diselesaikan otomatis."],["Saat pengumuman keluar, harga sering turun tajam karena banyak pemegang menjual. Jika Anda memegang token tersebut, putuskan apakah menjual di bursa itu atau menarik ke ",["dompet pribadi","non-custodial-wallet"]," sebelum batas waktu. Setelah penarikan ditutup, memulihkan aset bisa sulit."]],"example":"Misalkan Anda memegang 20.000 token seharga 0,05 USDT, total 1.000 USDT. Bursa mengumumkan perdagangan berhenti dalam 7 hari dan penarikan ditutup dalam 90 hari. Harga turun 40% menjadi 0,03 USDT dalam sehari, sehingga nilai Anda tinggal 600 USDT. Jika Anda ingin menyimpannya, Anda bisa menarik ke dompet pribadi, misalnya dengan biaya 200 token, sehingga tersisa 19.800 token. Jika Anda membiarkan aset sampai batas 90 hari lewat, Anda mungkin perlu prosedur khusus untuk mengklaimnya.","mistakes":["Mengabaikan pengumuman bursa sampai batas waktu penarikan terlewat.","Panik menjual tanpa membandingkan likuiditas token itu di bursa atau DEX lain.","Menarik token ke jaringan yang tidak didukung dompet tujuan karena terburu-buru."],"faq":[{"q":"Apa yang terjadi pada token saya jika di-delist?","a":"Perdagangan dihentikan dan Anda diberi waktu untuk menarik token ke dompet atau bursa lain. Token tetap ada di blockchain, tetapi tidak lagi bisa diperdagangkan di bursa tersebut."},{"q":"Apakah delisting berarti proyeknya penipuan?","a":"Tidak selalu. Delisting sering terjadi karena volume rendah atau alasan regulasi, tetapi pengumuman itu tetap sinyal untuk meninjau kembali proyek tersebut."}],"title":"Apa itu delisting kripto? Yang harus Anda lakukan","description":"Pahami arti delisting token, alasan bursa menghapus koin, jadwal penarikan, dan langkah yang perlu Anda ambil.","related":[["token-listing","Listing token","Listing token adalah proses ketika bursa menambahkan token baru ke daftar aset yang bisa disetor dan diperdagangkan, biasanya diumumkan lebih dulu beserta jadwal pembukaan setoran dan perdagangan."],["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["withdrawal-fee","Biaya penarikan (withdrawal fee)","Biaya penarikan adalah biaya yang dipotong bursa saat Anda menarik kripto ke alamat lain atau menarik rupiah ke rekening bank, biasanya berupa jumlah tetap per transaksi yang bergantung pada koin dan jaringan."],["rug-pull","Rug pull","Rug pull adalah penipuan di mana pengembang proyek kripto tiba-tiba menarik likuiditas, menjual token dalam jumlah besar, atau menyalahgunakan kontrak, sehingga harga token anjlok dan investor tidak bisa keluar."]],"lesson":null,"coin":null,"tool":"/activities","cta":false}});
